import re


class StackUnderflowError(Exception):
    pass


_NUMBER = re.compile(r"-?\d+")


def _tokenize(text):
    return re.findall(r"-?\d+|\S+", text)


def _trunc_div(a, b):
    if b == 0:
        raise ZeroDivisionError("divide by zero")
    quotient = abs(a) // abs(b)
    return -quotient if (a < 0) != (b < 0) else quotient


def evaluate(input_data):
    words = {}
    stack = []

    def pop():
        if not stack:
            raise StackUnderflowError("Insufficient number of items in stack")
        return stack.pop()

    def builtin(token):
        if token == "+":
            b = pop()
            a = pop()
            stack.append(a + b)
        elif token == "-":
            b = pop()
            a = pop()
            stack.append(a - b)
        elif token == "*":
            b = pop()
            a = pop()
            stack.append(a * b)
        elif token == "/":
            b = pop()
            a = pop()
            stack.append(_trunc_div(a, b))
        elif token == "dup":
            if not stack:
                raise StackUnderflowError("Insufficient number of items in stack")
            stack.append(stack[-1])
        elif token == "drop":
            pop()
        elif token == "swap":
            b = pop()
            a = pop()
            stack.append(b)
            stack.append(a)
        elif token == "over":
            if len(stack) < 2:
                raise StackUnderflowError("Insufficient number of items in stack")
            stack.append(stack[-2])
        else:
            raise ValueError("undefined operation")

    def execute(tokens):
        i = 0
        n = len(tokens)
        while i < n:
            token = tokens[i]
            i += 1
            if _NUMBER.fullmatch(token):
                stack.append(int(token))
            elif token == ":":
                if i >= n:
                    raise ValueError("illegal operation")
                name = tokens[i].lower()
                i += 1
                if _NUMBER.fullmatch(name):
                    raise ValueError("illegal operation")
                body = []
                while i < n and tokens[i] != ";":
                    word = tokens[i].lower()
                    i += 1
                    # Resolve user-defined words at definition time so that
                    # a word keeps the definition it referred to when defined.
                    body.extend(words.get(word, [word]))
                words[name] = body
            elif token == ";":
                pass
            elif token in words:
                execute(words[token])
            else:
                builtin(token)

    for line in input_data:
        execute(_tokenize(line))
    return stack

